query Query($where: WorkOrderProcessWhereInput, $orderBy: [WorkOrderProcessOrderByInput!], $first: Int, $after: String) {
  workOrderProcess(where: $where, orderBy: $orderBy, first: $first, after: $after) {
    edges {
      node {
        id
        workOrderId
        productStrategyProcess {
          workcenter {
            facilityId
            workcenterInputs {
              edges {
                node {
                  location {
                    id
                    inventories {
                      edges {
                        node {
                          id
                          active
                          quantity {
                            value
                            unitId
                          }
                          inventoryStatus {
                            active
                          }
                          productStrategyProcess {
                            id
                            productStrategy {
                              id
                              productId
                            }
                          }
                        }
                      }
                    }
                  }
                }
              }
            }
          }
        }
      }
    }
  }
}

query Query($where: WorkOrderProcessDistributionWhereInput, $orderBy: [WorkOrderProcessDistributionOrderByInput!], $first: Int, $after: String) {
  d:workOrderProcessDistribution(where: $where, orderBy: $orderBy, first: $first, after: $after) {
    edges {
      node {
        id
        balanceQuantity
        scheduledStartAt
        workOrderProcess {
          id
          quantity
          workOrderId
          productStrategyProcess {
            id
            workcenter {
              id
              facilityId
              workcenterInputs {
                edges {
                  node {
                    location {
                      id
                      inventories {
                        edges {
                          node {
                            id
                            active
                            quantity {
                              value
                              unitId
                            }
                            productStrategyProcess {
                              id
                              productStrategy {
                                id
                                productId
                              }
                            }
                          }
                        }
                      }
                    }
                  }
                }
              }
            }
          }
          workOrderProcessBoms {
            edges {
              node {
                standardUsage
                componentProductId
                componentProductStrategy{id consumptionUnitId}
                componentProductStrategyProcessId
              }
            }
          }
        }
      }
    }
  }
}

data.transform:
(

$g := $groupBy([$.d.edges.node], function ($v) { $v.workOrderProcess.productStrategyProcess.workcenter.workcenterInputs.edges[0].node.location.id });

$r :=  $each($g, function($v, $k) {(
   $date := $sort($v.scheduledStartAt[$!=null], function($l, $r) {
    $l > $r
  });
    $totals := $v.workOrderProcess.(
    $inv := $groupBy([productStrategyProcess.workcenter.workcenterInputs.edges.node.location.inventories.edges.node], function ($v) { $v.productStrategyProcess.id });
      $q := quantity;
     workOrderProcessBoms.edges.node.{
       "pspId":componentProductStrategyProcessId,
       "quantity": standardUsage * $q,
       "unit": componentProductStrategy.consumptionUnitId,
       "inv":$lookup($inv, componentProductStrategyProcessId)
     }
   );
  $p := $groupBy([$totals], function ($vv) { $vv.pspId });
   $t := $each($p, function($vvv, $kk) {(

     {
       "locationId": $k,
       "pspId": $kk,
       "quantity": $sum($vvv.quantity) - $coalesce([$sum($vvv.inv.quantity.value),0]),
       "unitId": $vvv[0].unit,
       "date": $date[0],
       "workcenterId": $v[0].workOrderProcess.productStrategyProcess.workcenter.id
     }
   )})   

)}); 

$flatten($r)
)

