query Query($where: ShipmentWhereInput, $orderBy: [ShipmentOrderByInput!], $first: Int, $after: String) {
  s:shipment(where: $where, orderBy: $orderBy, first: $first, after: $after) {
    edges {
      node {
        id
        shipmentStageId
        shipmentTypeId
        loadId
        salesOrderId
        transferOrderId
        scheduledShipAt
        shippingLocationId
        shipmentLines {
          edges {
            node {
              id
              loadedQuantity {value unitId}
              quantity {value unitId}
              shippedQuantity {value unitId}
              stagedQuantity {value unitId}
              shipmentLineStageId
              product {
                id 
                strategies(where: {
                  active: {_eq: true},
                  primary: { _eq: true}
                }) {
                  edges {
                    node{
                      strategyProcesses(where: {
                        active: {_eq: true}
                      },orderBy: {field:order,direction:desc}, first:1) {
                        edges {node{id}}
                      }
                    }
                  }
                }
              }
              salesOrderLineId
              transferOrderLineId
              andonRequests{edges{node{quantity{value unitId}}}}
            }
          }
        }
      }
    }
  }
}

